-- ═══════════════════════════════════════════════════════════════════
-- Catálogo CIE-10 (diagnósticos), fuente oficial: DGIS / Secretaría de
-- Salud México, vía datos.gob.mx (https://www.datos.gob.mx/dataset/catalogo_cie_10).
-- Tabla de REFERENCIA global compartida por todos los tenants (no lleva
-- tenant_id ni RLS a propósito: es el mismo catálogo público para
-- cualquier clínica, no hay "dueño" de un código CIE-10).
--
-- pg_trgm habilita búsqueda por substring tolerante a errores de tecleo
-- (ILIKE '%termino%') usando el índice GIN en vez de un table scan.
-- ═══════════════════════════════════════════════════════════════════

CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE TABLE IF NOT EXISTS cie10_diagnosticos (
  code        text PRIMARY KEY,
  descripcion text NOT NULL,
  capitulo    text NOT NULL
);

CREATE INDEX IF NOT EXISTS cie10_descripcion_trgm_idx
  ON cie10_diagnosticos USING gin (descripcion gin_trgm_ops);

CREATE INDEX IF NOT EXISTS cie10_code_trgm_idx
  ON cie10_diagnosticos USING gin (code gin_trgm_ops);

ON CONFLICT (code) DO NOTHING;

